/* Browser integration only: authored content and sprites are generated by Rust. */
const $ = (query, root = document) => root.querySelector(query);
const $$ = (query, root = document) => [...root.querySelectorAll(query)];
const activeSpecies = document.body.dataset.page === 'index' ? new Set($$('.pokemon-card').filter(card => card.dataset.cut !== 'true').map(card => card.dataset.id)) : null;
const storageKey = 'geothite.pokedex.notebook.v1';
let saved = new Set();
try { const value = JSON.parse(localStorage.getItem(storageKey) || '[]'); if (Array.isArray(value)) saved = new Set(value.filter(id => /^MN_\d{3}$/.test(id))); } catch { /* A private browser still gets a working guide. */ }
function paintNotebook() {
  $$('[data-save]').forEach(button => { const active = saved.has(button.dataset.save); button.setAttribute('aria-pressed', String(active)); button.textContent = active ? '★' : '☆'; button.setAttribute('aria-label', `${active ? 'Remove' : 'Save'} ${button.dataset.name || button.dataset.save} ${active ? 'from' : 'to'} notebook`); });
  $$('[data-saved-count]').forEach(node => { node.textContent = [...saved].filter(id => !activeSpecies || activeSpecies.has(id)).length; });
}
document.addEventListener('click', event => {
  const button = event.target.closest('[data-save]');
  if (!button) return;
  const id = button.dataset.save;
  if (saved.has(id)) saved.delete(id); else saved.add(id);
  try { localStorage.setItem(storageKey, JSON.stringify([...saved])); } catch { /* Memory-only notebook when storage is unavailable. */ }
  paintNotebook();
  if (document.body.dataset.page === 'index') updateIndex();
});
paintNotebook();
let updateIndex = () => {};
if (document.body.dataset.page === 'index') {
  const cards = $$('.pokemon-card');
  const families = $$('.family-card');
  const search = $('#dex-search');
  let selectedTypes = [];
  let notebook = false;
  let view = 'species';
  const normalize = text => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[_-]/g, ' ');
  function restore() {
    const params = new URLSearchParams(location.search);
    search.value = params.get('q') || '';
    selectedTypes = (params.get('type') || '').split(',').filter(value => $$('[data-type]').some(button => button.dataset.type === value)).slice(0, 2);
    notebook = params.get('notebook') === '1';
    $('#cut-filter').checked = params.get('cut') === '1';
    view = params.get('view') === 'families' ? 'families' : 'species';
    $('#region-filter').value = params.get('region') || '';
    $('#rarity-filter').value = params.get('rarity') || '';
    $('#sort-filter').value = 'number';
    updateIndex(false);
  }
  updateIndex = (writeUrl = true) => {
    const terms = normalize(search.value.trim()).split(/\s+/).filter(Boolean);
    const region = $('#region-filter').value;
    const rarity = $('#rarity-filter').value;
    const includeCut = $('#cut-filter').checked;
    const sort = 'number';
    const isFamily = view === 'families';
    $('#species-grid').hidden = isFamily; $('#family-grid').hidden = !isFamily;
    const entries = isFamily ? families : cards;
    const matchingCards = new Set();
    for (const card of cards) {
      const data = card.dataset;
      const matches = (includeCut || data.cut !== 'true')
        && terms.every(term => normalize(data.search).includes(term))
        && selectedTypes.every(type => data.types.split(' ').includes(type))
        && (!region || data.region === region)
        && (!notebook || saved.has(data.id))
        && (!rarity || (rarity === 'rare' ? ['legendary', 'mythical'].includes(data.rarity) : data.rarity === rarity));
      card.hidden = !matches;
      if (matches) matchingCards.add(data.family);
    }
    if (isFamily) families.forEach(card => { card.hidden = !matchingCards.has(card.dataset.family); });
    const container = isFamily ? $('#family-grid') : $('#species-grid');
    const ordered = [...entries].sort((a, b) => Number(a.dataset.cut === 'true') - Number(b.dataset.cut === 'true') || Number(a.dataset.number) - Number(b.dataset.number));
    ordered.forEach(card => container.append(card));
    const count = entries.filter(card => !card.hidden).length;
    const cutCount = entries.filter(card => !card.hidden && card.dataset.cut === 'true').length;
    $('#result-count').textContent = `${count} ${isFamily ? 'evolution line' : 'Pokémon'}${isFamily && count !== 1 ? 's' : ''} ${notebook ? 'in your notebook' : 'indexed'}${cutCount ? ` · ${cutCount} cut proposal${cutCount === 1 ? '' : 's'}` : ''}`;
    $('#empty-state').hidden = count !== 0;
    $$('[data-type]').forEach(button => button.setAttribute('aria-pressed', String(selectedTypes.includes(button.dataset.type))));
    $$('[data-view]').forEach(button => button.setAttribute('aria-pressed', String(view === button.dataset.view)));
    $('#notebook-filter').setAttribute('aria-pressed', String(notebook));
    activeSpecies.clear();
    cards.filter(card => includeCut || card.dataset.cut !== 'true').forEach(card => activeSpecies.add(card.dataset.id));
    paintNotebook();
    if (writeUrl) {
      const params = new URLSearchParams();
      for (const [key, value] of Object.entries({ q: search.value.trim(), type: selectedTypes.join(','), region, rarity, cut: includeCut ? '1' : '', sort: sort === 'number' ? '' : sort, notebook: notebook ? '1' : '', view: isFamily ? 'families' : '' })) if (value) params.set(key, value);
      const query = params.toString();
      history.replaceState(null, '', `${location.pathname}${query ? `?${query}` : ''}${location.hash}`);
    }
  };
  let debounce;
  search.addEventListener('input', () => { clearTimeout(debounce); debounce = setTimeout(updateIndex, 90); });
  $$('[data-type]').forEach(button => button.addEventListener('click', () => { const type = button.dataset.type; if (selectedTypes.includes(type)) selectedTypes = selectedTypes.filter(value => value !== type); else selectedTypes = [...selectedTypes.slice(-1), type]; updateIndex(); }));
  $$('[data-view]').forEach(button => button.addEventListener('click', () => { view = button.dataset.view; updateIndex(); }));
  for (const id of ['region-filter', 'rarity-filter', 'sort-filter', 'cut-filter']) $(`#${id}`).addEventListener('change', () => updateIndex());
  $('#notebook-filter').addEventListener('click', () => { notebook = !notebook; updateIndex(); });
  function reset() { search.value = ''; selectedTypes = []; notebook = false; $('#cut-filter').checked = false; $('#region-filter').value = ''; $('#rarity-filter').value = ''; $('#sort-filter').value = 'number'; updateIndex(); }
  $('#clear-filters').addEventListener('click', reset); $$('[data-reset]').forEach(button => button.addEventListener('click', reset));
  const small = matchMedia('(max-width:620px)');
  $('.filter-pane').open = !small.matches;
  small.addEventListener('change', event => { $('.filter-pane').open = !event.matches; });
  addEventListener('popstate', restore);
  document.addEventListener('keydown', event => { if (event.key === '/' && !event.ctrlKey && !event.metaKey && !['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName)) { event.preventDefault(); search.focus(); } if (event.key === 'Escape' && document.activeElement === search) search.blur(); });
  restore();
}
if (document.body.dataset.page === 'entry') {
  let facing = 'front'; let shiny = false;
  const portrait = $('#specimen-portrait');
  function paintPortrait() {
    portrait.src = portrait.dataset[`${shiny ? 'shiny' : 'normal'}${facing === 'front' ? 'Front' : 'Back'}`];
    portrait.alt = `${portrait.dataset.name}, ${shiny ? 'shiny' : 'normal'} ${facing} sprite`;
    document.body.dataset.shiny = String(shiny);
    syncWalkingPalette(shiny);
    $$('[data-facing]').forEach(button => button.setAttribute('aria-pressed', String(facing === button.dataset.facing)));
    $('#shiny-toggle').setAttribute('aria-pressed', String(shiny));
  }
  $$('[data-facing]').forEach(button => button.addEventListener('click', () => { facing = button.dataset.facing; paintPortrait(); }));
  $('#shiny-toggle').addEventListener('click', () => { shiny = !shiny; paintPortrait(); });
  const tabs = $$('[data-tab]');
  function selectTab(button) { tabs.forEach(tab => { const active = tab === button; tab.setAttribute('aria-selected', String(active)); tab.tabIndex = active ? 0 : -1; $(`#moves-${tab.dataset.tab}`).hidden = !active; }); }
  tabs.forEach((button, index) => { button.addEventListener('click', () => selectTab(button)); button.addEventListener('keydown', event => { if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; selectTab(tabs[next]); tabs[next].focus(); }); });
  document.addEventListener('keydown', event => { if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName) || event.ctrlKey || event.metaKey || event.altKey) return; if (event.key.toLowerCase() === 'f') { facing = facing === 'front' ? 'back' : 'front'; paintPortrait(); } if (event.key.toLowerCase() === 's') { shiny = !shiny; paintPortrait(); } });
}
// Stills are the default, including reduced-motion sessions; only explicit Play loads an APNG.
let stopActiveAnimation = null;
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
function stopAnimation() { if (stopActiveAnimation) stopActiveAnimation(); }
reducedMotion.addEventListener('change', event => { if (event.matches) stopAnimation(); });
document.addEventListener('visibilitychange', () => { if (document.hidden) stopAnimation(); });
const animationVisibility = typeof IntersectionObserver === 'function' ? new IntersectionObserver(entries => {
  entries.forEach(entry => { if (!entry.isIntersecting) entry.target.dispatchEvent(new Event('animation-offscreen')); });
}) : null;
$$('[data-animation-base]').forEach(preview => {
  let playing = false; let enemy = false; let shiny = false;
  const image = $('img', preview);
  const play = $('[data-animation-play]', preview);
  const side = $('[data-animation-side]', preview);
  const palette = $('[data-animation-shiny]', preview);
  const download = $('.animation-download', preview);
  function paint() {
    const animation = `${preview.dataset.animationBase}-${enemy ? 'enemy' : 'player'}-${shiny ? 'shiny' : 'normal'}`;
    image.src = `${animation}${playing ? '' : '-still'}.png`;
    image.alt = `${preview.dataset.moveName}, ${enemy ? 'enemy' : 'player'}-side ${shiny ? 'shiny' : 'normal'} battle ${playing ? 'animation' : 'preview'}`;
    play.textContent = playing ? 'Stop' : 'Play';
    play.setAttribute('aria-label', `${playing ? 'Stop' : 'Play'} ${preview.dataset.moveName} animation`);
    play.setAttribute('aria-pressed', String(playing));
    side.setAttribute('aria-pressed', String(enemy));
    palette.setAttribute('aria-pressed', String(shiny));
    download.href = `${animation}.png`;
  }
  function stop() { playing = false; paint(); if (stopActiveAnimation === stop) stopActiveAnimation = null; }
  play.addEventListener('click', () => {
    if (playing) { stop(); return; }
    stopAnimation(); playing = true; stopActiveAnimation = stop; paint();
  });
  side.addEventListener('click', () => { enemy = !enemy; paint(); });
  palette.addEventListener('click', () => { shiny = !shiny; paint(); });
  preview.addEventListener('animation-offscreen', stop);
  if (animationVisibility) animationVisibility.observe(preview);
});

// Native thumbnails use actual idle/step cells, never a scaled battle portrait.
function syncWalkingPalette(shiny) {
  $$('[data-walk-normal]').forEach(image => { image.src = shiny ? image.dataset.walkShiny : image.dataset.walkNormal; });
}
const walkers = $$('[data-walker]');
const visibleWalkers = new Set();
let walkingEnabled = true;
try { walkingEnabled = localStorage.getItem('geothite.pokedex.walking.v1') !== 'off'; } catch { /* Session-only preference. */ }
function paintWalking() {
  const enabled = walkingEnabled && !reducedMotion.matches;
  walkers.forEach(walker => walker.toggleAttribute('data-sprite-running', enabled && !document.hidden && visibleWalkers.has(walker)));
  $$('[data-walking-toggle]').forEach(button => {
    button.setAttribute('aria-pressed', String(enabled));
    button.textContent = enabled ? 'Pause sprites' : 'Play sprites';
    button.disabled = reducedMotion.matches;
  });
}
if (typeof IntersectionObserver === 'function') {
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => { if (entry.isIntersecting) visibleWalkers.add(entry.target); else visibleWalkers.delete(entry.target); });
    paintWalking();
  });
  walkers.forEach(walker => observer.observe(walker));
} else {
  walkers.forEach(walker => visibleWalkers.add(walker));
}
$$('[data-walking-toggle]').forEach(button => button.addEventListener('click', () => {
  walkingEnabled = !walkingEnabled;
  try { localStorage.setItem('geothite.pokedex.walking.v1', walkingEnabled ? 'on' : 'off'); } catch { /* Session-only preference. */ }
  paintWalking();
}));
reducedMotion.addEventListener('change', paintWalking);
document.addEventListener('visibilitychange', paintWalking);
paintWalking();

// A single media element prevents overlapping cries. Fetch only after a gesture.
const cryPlayer = new Audio();
cryPlayer.preload = 'none';
let activeCryButton = null;
let cryRequest = 0;
const cryStatus = document.createElement('span');
cryStatus.className = 'media-status';
cryStatus.setAttribute('role', 'status');
document.body.append(cryStatus);
function stopCry() {
  cryRequest += 1;
  cryPlayer.pause();
  if (activeCryButton) {
    activeCryButton.setAttribute('aria-pressed', 'false');
    activeCryButton.setAttribute('aria-label', `Play ${activeCryButton.dataset.cryName} cry`);
    activeCryButton.textContent = '▶ Cry';
    activeCryButton = null;
  }
}
cryPlayer.addEventListener('ended', stopCry);
cryPlayer.addEventListener('error', () => { if (activeCryButton) cryStatus.textContent = `Could not play ${activeCryButton.dataset.cryName}'s cry. Try again.`; stopCry(); });
window.addEventListener('pagehide', stopCry);
document.addEventListener('click', async event => {
  const button = event.target.closest('[data-cry]');
  if (!button) return;
  const same = activeCryButton === button;
  stopCry();
  if (same) return;
  const request = cryRequest;
  activeCryButton = button;
  button.setAttribute('aria-pressed', 'true');
  button.setAttribute('aria-label', `Stop ${button.dataset.cryName} cry`);
  button.textContent = '■ Stop';
  cryStatus.textContent = '';
  cryPlayer.src = button.dataset.cry;
  try { await cryPlayer.play(); } catch {
    if (request === cryRequest) {
      cryStatus.textContent = `Could not play ${button.dataset.cryName}'s cry. Try again.`;
      stopCry();
    }
  }
});
